def compute(vars):
    ball_return = vars["v1"]
    sp500_return = vars["v2"]
    difference = ball_return - sp500_return

    return {
        "value": difference,
        "trace": {
            "ball_return": ball_return,
            "sp500_return": sp500_return,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "index value"
            }
        }
    }
